B.Nm=new A.a(B.c,"Espere um relacionamento.")
B.Xe=new A.a(B.b,"Porque o maior milagre n\xe3o \xe9 Deus resolver sua vida r\xe1pido.")
B.Gm=new A.a(B.c,"\xc9 Ele te transformar em algu\xe9m que sabe viver com Ele.")
